/* Portafolio de Jorge Morales: íconos, tema, texto animado y galería */
(function () {
  var ICONS = {"javascript":{"n":"JavaScript","s":"data:image/svg+xml;base64,"},"typescript":{"n":"TypeScript","s":"data:image/svg+xml;base64,"},"nodejs":{"n":"Node.js","s":"data:image/svg+xml;base64,"},"express":{"n":"Express","s":"data:image/svg+xml;base64,"},"react":{"n":"React","s":"data:image/svg+xml;base64,"},"nextjs":{"n":"Next.js","s":"data:image/svg+xml;base64,"},"astro":{"n":"Astro","s":"data:image/svg+xml;base64,"},"tailwindcss":{"n":"Tailwind CSS","s":"data:image/svg+xml;base64,"},"python":{"n":"Python","s":"data:image/svg+xml;base64,"},"csharp":{"n":"C#","s":"data:image/svg+xml;base64,"},"dotnet":{"n":".NET","s":"data:image/svg+xml;base64,"},"graphql":{"n":"GraphQL","s":"data:image/svg+xml;base64,"},"postgresql":{"n":"PostgreSQL","s":"data:image/svg+xml;base64,"},"sqlserver":{"n":"SQL Server","s":"data:image/svg+xml;base64,"},"mysql":{"n":"MySQL","s":"data:image/svg+xml;base64,"},"oracle":{"n":"Oracle","s":"data:image/svg+xml;base64,"},"redis":{"n":"Redis","s":"data:image/svg+xml;base64,"},"docker":{"n":"Docker","s":"data:image/svg+xml;base64,"},"aws":{"n":"AWS","s":"data:image/svg+xml;base64,"},"azure":{"n":"Azure","s":"data:image/svg+xml;base64,"},"nginx":{"n":"nginx","s":"data:image/svg+xml;base64,"},"cloudflare":{"n":"Cloudflare","s":"data:image/svg+xml;base64,"},"playwright":{"n":"Playwright","s":"data:image/svg+xml;base64,"},"githubactions":{"n":"GitHub Actions","s":"data:image/svg+xml;base64,"},"git":{"n":"Git","s":"data:image/svg+xml;base64,"},"github":{"n":"GitHub","s":"data:image/svg+xml;base64,"},"powershell":{"n":"PowerShell","s":"data:image/svg+xml;base64,"},"bash":{"n":"Bash","s":"data:image/svg+xml;base64,"},"sentry":{"n":"Sentry","s":"data:image/svg+xml;base64,"},"vscode":{"n":"VS Code","s":"data:image/svg+xml;base64,"},"postman":{"n":"Postman","s":"data:image/svg+xml;base64,"},"eslint":{"n":"ESLint","s":"data:image/svg+xml;base64,"},"n8n":{"n":"n8n","s":"data:image/svg+xml;base64,"},"whatsapp":{"n":"WhatsApp Business","s":"data:image/svg+xml;base64,"},"googlesheets":{"n":"Google Sheets","s":"data:image/svg+xml;base64,"}};

  /* ---- Tema claro / oscuro ---- */
  var root = document.documentElement;
  function setTheme(t) {
    root.setAttribute('data-theme', t);
    try { localStorage.setItem('tema', t); } catch (e) {}
    document.querySelectorAll('.theme button').forEach(function (b) {
      b.setAttribute('aria-pressed', String(b.dataset.set === t));
    });
  }
  var current = root.getAttribute('data-theme') ||
    (window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light');
  document.querySelectorAll('.theme button').forEach(function (b) {
    b.setAttribute('aria-pressed', String(b.dataset.set === current));
    b.addEventListener('click', function () { setTheme(b.dataset.set); });
  });

  /* ---- Íconos de tecnologías ---- */
  function tile(key, withLabel) {
    var ic = ICONS[key];
    if (!ic) return null;
    if (withLabel) {
      var d = document.createElement('div');
      d.className = 'tech';
      d.innerHTML = '<span class="tile"><img alt="" src="' + ic.s + '"></span><small>' + ic.n + '</small>';
      return d;
    }
    var s = document.createElement('span');
    s.title = ic.n;
    s.innerHTML = '<img alt="' + ic.n + '" src="' + ic.s + '">';
    return s;
  }
  document.querySelectorAll('[data-tech]').forEach(function (el) {
    var keys = el.dataset.tech.split(',').map(function (k) { return k.trim(); });
    if (el.classList.contains('marquee')) {
      var track = document.createElement('div');
      track.className = 'track';
      [false, true].forEach(function (dup) {
        keys.forEach(function (k) {
          var t = tile(k, true);
          if (!t) return;
          if (dup) { t.classList.add('dup'); t.setAttribute('aria-hidden', 'true'); }
          track.appendChild(t);
        });
      });
      el.appendChild(track);
      el.setAttribute('aria-label', 'Tecnologías: ' + keys.map(function (k) { return ICONS[k] ? ICONS[k].n : k; }).join(', '));
      el.setAttribute('role', 'img');
    } else {
      keys.forEach(function (k) { var t = tile(k, false); if (t) el.appendChild(t); });
    }
  });

  var reduce = window.matchMedia && matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- Nombre que se escribe solo ---- */
  var typed = document.querySelector('[data-type]');
  if (typed && !reduce) {
    var text = typed.textContent;
    typed.textContent = '';
    var i = 0;
    (function step() {
      typed.textContent = text.slice(0, ++i);
      if (i < text.length) setTimeout(step, 85);
    })();
  }

  /* ---- Galería ---- */
  document.querySelectorAll('.carousel').forEach(function (c) {
    var track = c.querySelector('.slides');
    var slides = Array.prototype.slice.call(c.querySelectorAll('.slide'));
    var dotsBox = c.querySelector('.dots');
    var idx = 0;
    var dots = slides.map(function (s, n) {
      var b = document.createElement('button');
      b.type = 'button';
      b.setAttribute('aria-label', 'Ir a la pantalla ' + (n + 1));
      b.addEventListener('click', function () { go(n); });
      dotsBox.appendChild(b);
      return b;
    });
    function go(n) {
      n = Math.max(0, Math.min(slides.length - 1, n));
      var s = slides[n];
      track.scrollTo({ left: s.offsetLeft - (track.clientWidth - s.clientWidth) / 2, behavior: reduce ? 'auto' : 'smooth' });
    }
    function mark(n) {
      idx = n;
      slides.forEach(function (s, k) { s.classList.toggle('active', k === n); s.setAttribute('aria-hidden', String(k !== n)); });
      dots.forEach(function (d, k) { d.setAttribute('aria-current', String(k === n)); });
    }
    function nearest() {
      var mid = track.scrollLeft + track.clientWidth / 2, best = 0, dist = Infinity;
      slides.forEach(function (s, k) {
        var d = Math.abs(s.offsetLeft + s.clientWidth / 2 - mid);
        if (d < dist) { dist = d; best = k; }
      });
      return best;
    }
    var timer;
    track.addEventListener('scroll', function () {
      clearTimeout(timer);
      timer = setTimeout(function () { mark(nearest()); }, 60);
    });
    c.querySelector('.prev').addEventListener('click', function () { go(idx - 1); });
    c.querySelector('.next').addEventListener('click', function () { go(idx + 1); });
    c.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowLeft') go(idx - 1);
      if (e.key === 'ArrowRight') go(idx + 1);
    });
    mark(0);
  });

  /* ---- Foto: si no existe foto.jpg, se muestran las iniciales ---- */
  var photo = document.querySelector('.avatar img');
  if (photo) {
    var fallback = function () { photo.parentNode.innerHTML = '<span aria-hidden="true">JM</span>'; };
    if (photo.complete && photo.naturalWidth === 0) fallback();
    else photo.addEventListener('error', fallback);
  }
})();
